(() => {
  const css = `
    :root {
      --tw-slate-100: #f1f5f9;
      --tw-slate-300: #cbd5e1;
      --tw-slate-400: #94a3b8;
      --tw-slate-900: #0f172a;
      --tw-emerald-300: #6ee7b7;
      --tw-emerald-400: #34d399;
      --tw-emerald-500: #10b981;
      --tw-amber-300: #fcd34d;
      --tw-amber-400: #fbbf24;
      --tw-sky-400: #38bdf8;
      --tw-sky-500: #0ea5e9;
      --tw-violet-500: #8b5cf6;
      --tw-rose-500: #f43f5e;
      --tw-white: #ffffff;
    }

    body {
      margin: 0;
      min-height: 100vh;
      background: radial-gradient(circle at top left, rgba(16,185,129,0.3), transparent 30%), linear-gradient(135deg, #07131f 0%, #0f172a 45%, #111827 100%);
      color: var(--tw-slate-100);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    }

    * { box-sizing: border-box; }
    a, button, input, textarea, select { font: inherit; }

    .min-h-screen { min-height: 100vh; }
    .mx-auto { margin-left: auto; margin-right: auto; }
    .max-w-7xl { max-width: 80rem; }
    .flex { display: flex; }
    .flex-col { flex-direction: column; }
    .flex-wrap { flex-wrap: wrap; }
    .items-center { align-items: center; }
    .items-start { align-items: flex-start; }
    .justify-between { justify-content: space-between; }
    .justify-center { justify-content: center; }
    .grid { display: grid; }
    .gap-3 { gap: 0.75rem; }
    .gap-4 { gap: 1rem; }
    .gap-6 { gap: 1.5rem; }
    .space-y-2 > * + * { margin-top: 0.5rem; }
    .space-y-3 > * + * { margin-top: 0.75rem; }
    .space-y-6 > * + * { margin-top: 1.5rem; }
    .hidden { display: none !important; }
    .block { display: block; }
    .w-full { width: 100%; }
    .max-w-2xl { max-width: 42rem; }
    .px-3 { padding-left: 0.75rem; padding-right: 0.75rem; }
    .px-4 { padding-left: 1rem; padding-right: 1rem; }
    .px-5 { padding-left: 1.25rem; padding-right: 1.25rem; }
    .py-1 { padding-top: 0.25rem; padding-bottom: 0.25rem; }
    .py-2 { padding-top: 0.5rem; padding-bottom: 0.5rem; }
    .py-2\.5 { padding-top: 0.625rem; padding-bottom: 0.625rem; }
    .py-3 { padding-top: 0.75rem; padding-bottom: 0.75rem; }
    .py-4 { padding-top: 1rem; padding-bottom: 1rem; }
    .py-6 { padding-top: 1.5rem; padding-bottom: 1.5rem; }
    .p-3 { padding: 0.75rem; }
    .p-4 { padding: 1rem; }
    .p-6 { padding: 1.5rem; }
    .mt-1 { margin-top: 0.25rem; }
    .mt-2 { margin-top: 0.5rem; }
    .mt-3 { margin-top: 0.75rem; }
    .mt-4 { margin-top: 1rem; }
    .mt-6 { margin-top: 1.5rem; }
    .mt-8 { margin-top: 2rem; }
    .mb-3 { margin-bottom: 0.75rem; }
    .mb-4 { margin-bottom: 1rem; }
    .mb-6 { margin-bottom: 1.5rem; }
    .ml-0 { margin-left: 0; }
    .mr-0 { margin-right: 0; }
    .rounded-full { border-radius: 9999px; }
    .rounded-2xl { border-radius: 1rem; }
    .rounded-3xl { border-radius: 1.5rem; }
    .rounded-\[28px\] { border-radius: 28px; }
    .rounded-\[32px\] { border-radius: 32px; }
    .border { border: 1px solid; }
    .border-white\/10 { border-color: rgba(255,255,255,0.1); }
    .border-emerald-400\/30 { border-color: rgba(52,211,153,0.3); }
    .border-amber-400\/30 { border-color: rgba(251,191,36,0.3); }
    .border-sky-400\/20 { border-color: rgba(56,189,248,0.2); }
    .border-rose-400\/30 { border-color: rgba(251,113,133,0.3); }
    .bg-white\/5 { background-color: rgba(255,255,255,0.05); }
    .bg-white\/10 { background-color: rgba(255,255,255,0.1); }
    .bg-emerald-500\/10 { background-color: rgba(16,185,129,0.1); }
    .bg-emerald-500\/90 { background-color: rgba(16,185,129,0.9); }
    .bg-emerald-500 { background-color: var(--tw-emerald-500); }
    .bg-amber-400\/10 { background-color: rgba(251,191,36,0.1); }
    .bg-amber-400\/90 { background-color: rgba(251,191,36,0.9); }
    .bg-amber-400 { background-color: var(--tw-amber-400); }
    .bg-sky-500\/10 { background-color: rgba(14,165,233,0.1); }
    .bg-sky-500\/80 { background-color: rgba(14,165,233,0.8); }
    .bg-sky-500 { background-color: var(--tw-sky-500); }
    .bg-violet-500\/80 { background-color: rgba(139,92,246,0.8); }
    .bg-rose-500\/10 { background-color: rgba(244,63,94,0.1); }
    .bg-rose-500\/80 { background-color: rgba(244,63,94,0.8); }
    .bg-slate-900\/70 { background-color: rgba(15,23,42,0.7); }
    .bg-slate-950\/60 { background-color: rgba(2,6,23,0.6); }
    .bg-white\/5 { background-color: rgba(255,255,255,0.05); }
    .text-slate-100 { color: var(--tw-slate-100); }
    .text-slate-300 { color: var(--tw-slate-300); }
    .text-slate-400 { color: var(--tw-slate-400); }
    .text-white { color: var(--tw-white); }
    .text-emerald-200 { color: #a7f3d0; }
    .text-emerald-300 { color: var(--tw-emerald-300); }
    .text-amber-100 { color: #fef3c7; }
    .text-amber-200 { color: #fde68a; }
    .text-sky-100 { color: #dbeafe; }
    .text-rose-200 { color: #fecdd3; }
    .text-sm { font-size: 0.875rem; }
    .text-lg { font-size: 1.125rem; }
    .text-2xl { font-size: 1.5rem; }
    .text-3xl { font-size: 1.875rem; }
    .text-4xl { font-size: 2.5rem; }
    .font-semibold { font-weight: 600; }
    .leading-tight { line-height: 1.2; }
    .uppercase { text-transform: uppercase; }
    .tracking-\[0\.25em\] { letter-spacing: 0.25em; }
    .tracking-\[0\.35em\] { letter-spacing: 0.35em; }
    .shadow-2xl { box-shadow: 0 25px 50px -12px rgba(0,0,0,0.4); }
    .shadow-emerald-500\/30 { box-shadow: 0 0 0 1px rgba(16,185,129,0.3), 0 20px 30px rgba(16,185,129,0.12); }
    .shadow-amber-400\/30 { box-shadow: 0 0 0 1px rgba(251,191,36,0.3), 0 20px 30px rgba(251,191,36,0.12); }
    .shadow-black\/30 { box-shadow: 0 25px 50px -12px rgba(0,0,0,0.3); }
    .backdrop-blur { backdrop-filter: blur(8px); }
    .transition { transition: all 0.2s ease; }
    .hover\:bg-emerald-400:hover { background-color: #34d399; }
    .hover\:bg-amber-300:hover { background-color: #fcd34d; }
    .hover\:bg-white\/20:hover { background-color: rgba(255,255,255,0.2); }
    .hover\:bg-white\/10:hover { background-color: rgba(255,255,255,0.1); }
    .hover\:bg-sky-400:hover { background-color: #38bdf8; }
    .hover\:bg-violet-400:hover { background-color: #a78bfa; }
    .hover\:bg-rose-400:hover { background-color: #fb7185; }
    .leading-\[0\.25em\] { line-height: 0.25em; }
    .h-100 { height: 100%; }
    .inline-flex { display: inline-flex; }
    .rounded-2xl { border-radius: 1rem; }
    .rounded-xl { border-radius: 0.75rem; }
    .outline-none { outline: none; }
    .focus\:outline-none:focus { outline: none; }
    .text-left { text-align: left; }
    .text-right { text-align: right; }
    .border-0 { border-width: 0; }
    .border-2 { border-width: 2px; }
    .text-slate-900 { color: #0f172a; }
    .placeholder\:text-slate-400::placeholder { color: var(--tw-slate-400); }
    .focus\:border-emerald-400:focus { border-color: var(--tw-emerald-400); }
    .focus\:border-amber-400:focus { border-color: var(--tw-amber-400); }
    .focus\:border-sky-400:focus { border-color: var(--tw-sky-400); }
    .focus\:border-rose-400:focus { border-color: var(--tw-rose-400); }
    .px-3.py-2 { padding-left: 0.75rem; padding-right: 0.75rem; padding-top: 0.5rem; padding-bottom: 0.5rem; }
    .w-full.rounded-xl { width: 100%; border-radius: 0.75rem; }
    input, textarea, select {
      border: 1px solid rgba(255,255,255,0.1);
      background: rgba(2,6,23,0.6);
      color: var(--tw-white);
      padding: 0.5rem 0.75rem;
      border-radius: 0.75rem;
      width: 100%;
    }
    textarea { min-height: 84px; }
    button { cursor: pointer; }
    .nav-btn { display: block; width: 100%; }
    .section-card { display: block; }
    .space-y-2 > div + div { margin-top: 0.5rem; }
    .space-y-6 > div + div { margin-top: 1.5rem; }
    .md\:grid-cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    @media (min-width: 768px) { .md\:grid-cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
    @media (min-width: 1024px) { .lg\:grid-cols-\[260px_1fr\] { grid-template-columns: 260px minmax(0, 1fr); } .lg\:flex-row { flex-direction: row; } .lg\:items-center { align-items: center; } .lg\:justify-between { justify-content: space-between; } }
    @media (min-width: 1280px) { .xl\:grid-cols-\[0\.9fr_1\.1fr\] { grid-template-columns: 0.9fr 1.1fr; } .xl\:p-8 { padding: 2rem; } }
    .md\:px-6 { padding-left: 1.5rem; padding-right: 1.5rem; }
    .lg\:px-8 { padding-left: 2rem; padding-right: 2rem; }
    .sm\:px-6 { padding-left: 1.5rem; padding-right: 1.5rem; }
    .sm\:text-4xl { font-size: 2.5rem; }
    .sm\:text-3xl { font-size: 1.875rem; }
    .xl\:grid-cols-\[0\.9fr_1\.1fr\] { grid-template-columns: 0.9fr 1.1fr; }
    .sm\:px-6 { padding-left: 1.5rem; padding-right: 1.5rem; }
    .md\:grid-cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    .text-3xl { font-size: 1.875rem; }
    .text-4xl { font-size: 2.5rem; }
    .font-semibold { font-weight: 600; }
    .float-none { float: none; }
    .list-none { list-style: none; }
    .prose { line-height: 1.6; }
  `;

  const style = document.createElement('style');
  style.setAttribute('data-tailwind-vendored', 'true');
  style.textContent = css;
  document.head.appendChild(style);

  const initButtons = () => {
    document.querySelectorAll('.nav-btn').forEach((button) => {
      button.addEventListener('click', () => {
        const target = button.dataset.target;
        document.querySelectorAll('.section-card').forEach((section) => {
          section.classList.toggle('hidden', section.id !== target);
        });
        document.querySelectorAll('.nav-btn').forEach((btn) => {
          btn.classList.toggle('bg-emerald-500/90', btn === button);
          btn.classList.toggle('bg-white/5', btn !== button);
        });
      });
    });
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initButtons, { once: true });
  } else {
    initButtons();
  }
})();
